mapper.select:
SELECT c.id AS chunk_id, c.document_id, d.source_id, s.name AS source_name, d.path, d.title, c.heading_path, c.heading_level, c.content, COALESCE((c.metadata ->> 'startLine')::int, 0) AS start_line, COALESCE((c.metadata ->> 'endLine')::int, 0) AS end_line, (
(CASE WHEN d.path ILIKE '%' || #{kw} || '%' THEN 4 ELSE 0 END + CASE WHEN d.title ILIKE '%' || #{kw} || '%' THEN 4 ELSE 0 END + CASE WHEN c.heading_path ILIKE '%' || #{kw} || '%' THEN 3 ELSE 0 END + CASE WHEN c.content ILIKE '%' || #{kw} || '%' THEN 1 ELSE 0 END)
) AS score FROM ai_knowledge_chunk c JOIN ai_knowledge_document d ON d.id = c.document_id JOIN ai_knowledge_source s ON s.id = d.source_id WHERE d.source_id IN #{sid} AND (
d.path ILIKE '%' || #{kw} || '%' OR d.title ILIKE '%' || #{kw} || '%' OR c.heading_path ILIKE '%' || #{kw} || '%' OR c.content ILIKE '%' || #{kw} || '%'
) ORDER BY score DESC, length(c.content) DESC, c.id ASC LIMIT #{limit}
